# Regenerate directly from the horizontal analogue shown in demo 4.
G = [[7]*19] + [[7]+[0]*17+[7] for _ in range(5)] + [[7]+[3]*17+[7]] + [[7,0,2,2,2,0,0,2,2,2,0,0,2,2,2,0,0,2,7] for _ in range(3)] + [[7]+[3]*17+[7]] + [[7]+[0]*17+[7] for _ in range(3)] + [[7]*19]
red_cols = {c for row in G for c,v in enumerate(row) if v==2}
O = []
for row in G:
    if 3 in row:
        O.append([3]*19)
    elif 2 in row:
        O.append([2 if v==2 else 0 for v in row])
    else:
        O.append([7 if c in red_cols else 0 for c in range(19)])
print(len(G),len(O),[len(r) for r in O])
print(json.dumps({'action':'submit','grid':O}))
